CREATE TABLE webhook_endpoints (id UUID PRIMARY KEY, name TEXT NOT NULL, url TEXT NOT NULL, enabled BOOLEAN NOT NULL, event_types TEXT[] NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE events (id UUID PRIMARY KEY, event_type TEXT NOT NULL, payload JSONB NOT NULL, idempotency_key TEXT UNIQUE, payload_sha256 TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE delivery_jobs (id UUID PRIMARY KEY, event_id UUID NOT NULL REFERENCES events(id), endpoint_id UUID NOT NULL REFERENCES webhook_endpoints(id), status TEXT NOT NULL CHECK (status IN ('QUEUED','IN_PROGRESS','RETRY_SCHEDULED','SUCCEEDED','DEAD')), attempt_count INT NOT NULL DEFAULT 0, max_attempts INT NOT NULL DEFAULT 5, next_attempt_at TIMESTAMPTZ, lease_owner TEXT, lease_expires_at TIMESTAMPTZ, last_http_status INT, last_error_code TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(event_id,endpoint_id));
CREATE INDEX delivery_jobs_status_due_idx ON delivery_jobs(status,next_attempt_at);
CREATE TABLE delivery_attempts (id UUID PRIMARY KEY, delivery_job_id UUID NOT NULL REFERENCES delivery_jobs(id), attempt_number INT NOT NULL, started_at TIMESTAMPTZ NOT NULL, finished_at TIMESTAMPTZ, outcome TEXT CHECK (outcome IN ('SUCCESS','TRANSIENT_FAILURE','PERMANENT_FAILURE','UNKNOWN')), http_status INT, duration_ms BIGINT, error_code TEXT, error_summary TEXT);
CREATE TABLE outbox_messages (id UUID PRIMARY KEY, delivery_job_id UUID NOT NULL REFERENCES delivery_jobs(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), published_at TIMESTAMPTZ, lease_owner TEXT, lease_expires_at TIMESTAMPTZ, publish_attempts INT NOT NULL DEFAULT 0);
CREATE INDEX outbox_unpublished_idx ON outbox_messages(created_at) WHERE published_at IS NULL;
